  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure, incompatibility, or missing prerequisite identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure or unsatisfied prerequisite, such as a failed import or a missing required tool/library.",
      "target_description": "A subsequent agent action intended to resolve that failure or satisfy the missing prerequisite."
    },
    {
      "name": "IDENTIFIES_INCOMPATIBLE_CODE",
      "definition": "A diagnostic search or static-analysis action performed over the codebase that surfaces specific code locations or constructs requiring modification for the target runtime environment.",
      "source_description": "A codebase scanning or analysis action executed to find problematic patterns.",
      "target_description": "The set of code locations or constructs revealed as incompatible and needing change."
    },
    {
      "name": "DERIVES_BUILD_REQUIREMENTS_FROM_CONFIGURATION",
      "definition": "An inspection of a project's build or packaging configuration that yields the build targets and requirements the agent must subsequently produce.",
      "source_description": "A build or packaging configuration artifact being inspected.",
      "target_description": "The build targets or requirements derived from that configuration and used to plan subsequent build actions."
    }
  ]
}

